import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.ArrayList;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TimeZone;
import org.apache.commons.lang.Validate;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for FastDateFormat.getDateTimeInstance
 */
public class FastDateFormat_getDateTimeInstance_TriageGen2Test {

    @Test
    public void testGetDateTimeInstance_WithAllParameters() {
        int dateStyle = java.text.DateFormat.MEDIUM;
        int timeStyle = java.text.DateFormat.SHORT;
        TimeZone timeZone = TimeZone.getTimeZone("GMT");
        Locale locale = Locale.US;

        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull("Format should not be null", format);
        assertEquals("TimeZone should match", timeZone, format.getTimeZone());
        assertEquals("Locale should match", locale, format.getLocale());
    }

    @Test
    public void testGetDateTimeInstance_WithNullTimeZone() {
        int dateStyle = java.text.DateFormat.FULL;
        int timeStyle = java.text.DateFormat.FULL;
        TimeZone timeZone = null;
        Locale locale = Locale.FRANCE;

        // This tests the branch: if (timeZone != null)
        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull("Format should not be null", format);
        assertEquals("Locale should match", locale, format.getLocale());
        // Since timeZone is null, the internal implementation usually defaults to system timezone
        // but we verify the object is created successfully.
    }

    @Test
    public void testGetDateTimeInstance_WithNullLocale() {
        int dateStyle = java.text.DateFormat.SHORT;
        int timeStyle = java.text.DateFormat.SHORT;
        TimeZone timeZone = TimeZone.getDefault();
        Locale locale = null;

        // This tests the branch: if (locale == null) { locale = Locale.getDefault(); }
        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull("Format should not be null", format);
        assertEquals("Locale should default to system locale", Locale.getDefault(), format.getLocale());
    }

    @Test
    public void testGetDateTimeInstance_CachingBehavior() {
        int dateStyle = java.text.DateFormat.LONG;
        int timeStyle = java.text.DateFormat.LONG;
        TimeZone timeZone = TimeZone.getTimeZone("UTC");
        Locale locale = Locale.UK;

        // First call to populate cache
        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        // Second call with same parameters to test cache hit
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull(format1);
        assertNotNull(format2);
        assertSame("Subsequent calls with same parameters should return the same cached instance", format1, format2);
    }

    @Test
    public void testGetDateTimeInstance_Functionality() {
        int dateStyle = java.text.DateFormat.MEDIUM;
        int timeStyle = java.text.DateFormat.MEDIUM;
        TimeZone timeZone = TimeZone.getTimeZone("UTC");
        Locale locale = Locale.US;

        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        Date date = new Date(1609459200000L); // 2021-01-01 00:00:00 UTC
        String formatted = format.format(date);

        assertNotNull(formatted);
        assertFalse("Formatted string should not be empty", formatted.isEmpty());
    }
}
